input.command:
npm install resend 2>&1 | tail -3
mkdir -p src/emails
cat > src/lib/resend.ts <<'EOF'
import { Resend } from "resend";

export const resend = new Resend(process.env.RESEND_API_KEY!);
EOF
cat > src/lib/email.ts <<'EOF'
import { resend } from "@/lib/resend";

const appUrl = () => process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000";

const escapeHtml = (s: string) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");

// Resolves to false (never throws) so a failed email doesn't break the request that triggered it.
async function send(to: string, subject: string, html: string, text: string): Promise<boolean> {
  try {
    const { error } = await resend.emails.send({
      from: process.env.RESEND_FROM_EMAIL!,
      to,
      subject,
      html,
      text,
    });
    if (error) {
      console.error(`[email] "${subject}" failed: ${error.name}: ${error.message}`);
      return false;
    }
    return true;
  } catch (err) {
    console.error(`[email] "${subject}" failed:`, err);
    return false;
  }
}

export function sendWelcomeEmail(user: { email: string; name: string }) {
  const url = `${appUrl()}/dashboard`;
  return send(
    user.email,
    "Welcome to Notely",
    `<p>Hi ${escapeHtml(user.name)},</p><p>Welcome to Notely! <a href="${url}">Open your dashboard</a> to start taking notes.</p>`,
    `Hi ${user.name},\n\nWelcome to Notely! Open your dashboard to start taking notes: ${url}`,
  );
}

export function sendPasswordResetEmail(user: { email: string; name: string }, token: string) {
  const url = `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;
  return send(
    user.email,
    "Reset your Notely password",
    `<p>Hi ${escapeHtml(user.name)},</p><p><a href="${url}">Reset your password</a>. This link expires in 1 hour. If you didn't request it, you can ignore this email.</p>`,
    `Hi ${user.name},\n\nReset your password (link expires in 1 hour): ${url}\n\nIf you didn't request this, ignore this email.`,
  );
}
EOF
rmdir src/emails
cat > .env.example <<'EOF'
# Resend (https://resend.com) — create a key under API Keys in the dashboard
RESEND_API_KEY=re_placeholder
# Must be on a domain verified in Resend (or onboarding@resend.dev while testing)
RESEND_FROM_EMAIL=Notely <onboarding@resend.dev>
# Base URL used in email links
NEXT_PUBLIC_APP_URL=http://localhost:3000
EOF
printf '!.env.example\n' >> .gitignore
python3 - <<'EOF'
p="src/lib/users.ts"
s=open(p).read()
s='import { randomBytes, createHash } from "node:crypto";\nimport { sendPasswordResetEmail, sendWelcomeEmail } from "@/lib/email";\n\n'+s
s+='''
export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

// Silently does nothing for unknown emails so callers can't probe which addresses have accounts.
export async function requestPasswordReset(email: string): Promise<void> {
  const user = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  await sendPasswordResetEmail(user, token);
}

// Single-use: returns the user the token belongs to and invalidates it, or undefined if invalid/expired.
export async function consumePasswordResetToken(token: string): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return getUser(entry.userId);
}
'''
open(p,"w").write(s)
EOF
npx tsc --noEmit && npx eslint src; git status --short

